// 순서 = 계산 결과 번호 0~35 (0 = 양자리 0~10°, 1 = 양자리 10~20°, … 35 = 물고기자리 20~30°). 바꾸지 말 것.
//
//   code             코드용 이름
//   sign / part      별자리(열대 12궁) / 몇 번째 데칸(1~3). 화면 "양자리 · 첫째 데칸"은 data.js TEXT.decan.partNames로 조립
//   facts.egyptian   이 데칸의 이집트 이름. Wikipedia "Decan"의 Names of the Decans 표 Greco-Egyptian names 열을
//                    2026-09-28 WebFetch 요약으로 옮김 — 원문 대조 미확인. 확인하지 못하면 "" (빈 글자)로 두면 화면에서 그 줄이 빠진다
//   facts.ruler      다스리는 별 (헬레니즘 점성술의 "칼데아 순서": 화성·태양·금성·수성·달·토성·목성 반복)
//   traits           후보 고르기 카드 공감 문장 2개 (각 45자). 태어난 날 태양이 칸을 넘은 사람만 본다
//   공통 네 장 (별의 방 data-stars.js와 같은 모양)
//   identity      첫째 장(정체): title(목차 16자), lede = 첫 문단(강조, 80자) → 사실 목록(facts) → body 단락들 → 해석 안내 한 줄
//   event         둘째 장(사건): hook = 첫째 장 끝 떡밥(45자), title(16자), lede(80자), body, quote(50자, 둘째 단락 뒤)
//   shadow        셋째 장(그림자): hook = 둘째 장 끝 떡밥, title, lede, body, quote
//   advice        넷째 장(다음): hook = 셋째 장 끝 떡밥, title, lede, body. 실행 가능한 긍정적 조언으로 끝낸다 (CLAUDE.md 8장)
//   summary       나의 이야기 요약 (문단 배열, 합계 300~500자)
//   단락 하나는 250자 이하(권장 120~250). 분량 목표(운영자 결정 26번): 결과 하나 3,000~4,000자
//
//   공통 짧은 칸
//   title         캡처 카드 제목 · 공유 카드 제목 (14자, 2줄)
//   key           캡처 카드 핵심 문장 + 공유 카드 본문 (60자, 3줄)
//   keywords      키워드 3개 (각 8자) — 지금은 화면에 쓰지 않음(나중 공유·요약용 예비)
//   archetype     원형 태그 (warrior sage lover rebel caregiver explorer creator ruler). 이름은 data.js TEXT.archetypes. 바꾸면 분포도 다시 볼 것
//   archetypeWhy  결과 화면 "이 방에서 얻은 원형" 근거 한 줄 (60자)
//   turn          반전(공감) 카드 문단 (180자, HTML 가능)
//   fact          결과 아래 문화 상식 카드 (150자, HTML 가능)
//   떡밥(다음 방으로 가는 문장)은 방마다 같은 문장이라 data.js TEXT.next[지금 방][가는 방]에 있다.
//
// 모든 초안 표시은 copywriter가 실제 문구로 바꾼다. 초안 표시이 남은 채로 출시하지 않는다 (CLAUDE.md 3장).
// 한 항목 = "  {" 로 시작해 "  }," 로 끝나는 한 덩어리 (분할·재조립 도구가 이 모양에 기댄다. 들여쓰기를 바꾸지 말 것)
// ═══════════════════════════════════════════════════════════════════════

